def Strongest_Extension(class_name, extensions):
    strongest_extension_name = extensions[0]
    strongest_strength = sum(1 for c in strongest_extension_name if c.isupper()) - sum(1 for c in strongest_extension_name if c.islower())

    for current_extension in extensions[1:]:
        current_strength = sum(1 for c in current_extension if c.isupper()) - sum(1 for c in current_extension if c.islower())
        if current_strength > strongest_strength:
            strongest_extension_name = current_extension
            strongest_strength = current_strength

    return f"{class_name}.{strongest_extension_name}"

