{
    var strongestExtensionName := extensions[0];
    var strongestStrength := CountUppercase(strongestExtensionName) - CountLowercase(strongestExtensionName);

    var i := 1;
    while i < extensions.Length
        invariant 0 <= i <= extensions.Length
        invariant strongestStrength == CountUppercase(strongestExtensionName) - CountLowercase(strongestExtensionName)
        invariant forall j: int :: 0 <= j < i ==> 
            (CountUppercase(extensions[j]) - CountLowercase(extensions[j]) <= strongestStrength)
    {
        var currentExtension := extensions[i];
        var currentStrength := CountUppercase(currentExtension) - CountLowercase(currentExtension);
        if currentStrength > strongestStrength {
