function CountUppercase(s: string) : int 
    reads s
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountUppercase(s[0..i])
    {
        if s[i] >= 'A' && s[i] <= 'Z' {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}

function CountLowercase(s: string) : int 
    reads s
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountLowercase(s[0..i])
    {
        if s[i] >= 'a' && s[i] <= 'z' {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}
